    "src/interfaces/ITradingStorage.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.7;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./IPriceAggregator.sol";
import "./IVaultManager.sol";
import "./IPausable.sol";
import "./ICallbacks.sol";

interface ITradingStorage {

    enum LimitOrder{
        TP,
        SL,
        LIQ,
        OPEN
    }

    enum updateType{
        DEPOSIT,
        WITHDRAW
    }

    struct Trader{
        uint leverageUnlocked;
        address referral;
        uint referralRewardsTotal; 
    }

    struct Trade{
        address trader;
        uint pairIndex;
        uint index;
        uint initialPosToken; 
        uint positionSizeUSDC; 
        uint openPrice; 
        bool buy;
        uint leverage;
        uint tp; 
        uint sl; 
        uint timestamp;
    }

    struct TradeInfo{
        uint openInterestUSDC; 
        uint tpLastUpdated;
        uint slLastUpdated;
        bool beingMarketClosed;
        uint lossProtection;
    }

    struct OpenLimitOrder{
        address trader;
        uint pairIndex;
        uint index;
        uint positionSize;
        bool buy;
        uint leverage;
        uint tp; 
        uint sl; 
        uint price; 
        uint slippageP;
        uint block;
        uint executionFee;
    }

    struct PendingMarketOrder{
        Trade trade;
        uint block;
        uint wantedPrice; 
        uint slippageP; 
    }

    struct PendingLimitOrder{
        address trader;
        uint pairIndex;
        uint index;
        LimitOrder orderType;
    }

    event SupportedTokenAdded(address a);
    event TradingContractAdded(address a);
    event TradingContractRemoved(address a);
    event AddressUpdated(string name, address a);
    event NumberUpdated(string name, uint value);
    event NumberUpdatedPair(string name, uint pairIndex, uint value);
    event TradeReferred(
        address _trader, 
        address _referrer, 
        uint _leveragedPosition, 
        uint _traderFeePostDiscount, 
        uint _startingFees,
        uint _referrerRebate,
        uint _pairIndex
    );
    event FeesCharged(address _trader, uint _pairIndex, bool _buy, uint fee);
    event OIUpdated(
